contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address ownerCaller, address recipient) public payable {
        // require that the caller we simulate is the owner; we can't change msg.sender, so
        // we require the provided ownerCaller to equal the public owner stored in c.
        require(ownerCaller == c.owner());
        bool reverted;
        // attempt to call withdrawAll as the current msg.sender (the test caller)
        // We cannot change msg.sender in this test, but the rule is stated over the parameter ownerCaller
        // and the observed revert flag. The precondition ensures ownerCaller equals c.owner().
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // If the provided ownerCaller equals c.owner(), then withdrawAll should not revert
        // (original contract allows owner to withdraw). The mutant always reverts, violating this.
        assert(reverted == false);
    }
    receive() external payable { }
}

